/* @component: textarea-field */
(function () {
  function initTextareaInputs() {
    document.querySelectorAll('.field-textarea.js-container-input').forEach(function (fs) {
      if (fs.dataset.initialized === 'true') return;
      fs.dataset.initialized = 'true';
      const label = fs.querySelector('label');
      const legendSpan = fs.querySelector('legend span');
      if (label && legendSpan) {
        legendSpan.textContent = label.textContent;
      }
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initTextareaInputs);
  } else {
    initTextareaInputs();
  }
  setTimeout(initTextareaInputs, 300);
})();
/* @end: textarea-field */
